const identifyTaskDB=[{"s":"Separa el tiempo de la historia del tiempo del relato en tres ejes: orden, duración y frecuencia.","type":"El tiempo del relato (Genette, 1972)"},{"s":"Distingue los hechos en su orden real (la fábula) del orden en que se cuentan (la trama).","type":"Fábula y trama (Shklovski, 1917; Tomashevski, 1925)"},{"s":"El público sabe algo que el personaje no sabe; se sostiene la tensión un buen rato.","type":"El suspense (Hitchcock, vía Truffaut, 1966)"},{"s":"Un susto breve, sin ningún aviso previo al público.","type":"La sorpresa (Hitchcock, vía Truffaut, 1966)"},{"s":"Ordena el interés narrativo en tres relojes: suspense, curiosidad y sorpresa.","type":"Los tres relojes (Sternberg, 1978)"},{"s":"Lo que el relato calla no es ausencia: es trabajo que el lector hace.","type":"La elipsis y los huecos (Iser, 1976)"},{"s":"Empezar la historia en mitad de las cosas, en vez de desde el principio.","type":"In medias res (Horacio, hacia el 18 a.C.)"},{"s":"El Quijote corta una batalla con las espadas en alto, al final de un capítulo.","type":"El corte de suspense del Quijote (1605)"},{"s":"Herramienta de esta etapa con tres casillas: el orden, la duración, lo que el lector sabe.","type":"El reloj del relato"},{"s":"Una palabra en una pregunta cambia el recuerdo de la velocidad de un choque de autos.","type":"La memoria reconstructiva (Loftus y Palmer, 1974)"}];
const classifyTaskDB=[{"w":"El tiempo del relato","gen":"Taxonomía","n":"Orden, duración y frecuencia","g":"Análisis estructuralista","t":"Genette, 1972"},{"w":"Fábula y trama","gen":"Distinción fundacional","n":"Los hechos en su orden, y el orden en que se cuentan","g":"Formalismo ruso","t":"Shklovski, 1917; Tomashevski, 1925"},{"w":"Suspense y sorpresa","gen":"Poética de oficio","n":"Dar el dato antes, o golpear sin aviso","g":"Reflexión de cineasta","t":"Hitchcock, vía Truffaut, 1966"},{"w":"Los tres relojes","gen":"Modelo teórico","n":"Suspense, curiosidad y sorpresa","g":"Crítica académica","t":"Sternberg, 1978"},{"w":"La elipsis y los huecos","gen":"Teoría de la recepción","n":"Lo que se calla, y que el lector rellena","g":"Estética de la lectura","t":"Iser, 1976"},{"w":"In medias res","gen":"Precepto clásico","n":"Empezar por la mitad","g":"Retórica poética","t":"Horacio, hacia el 18 a.C."},{"w":"El corte del Quijote","gen":"Caso comprobable","n":"Batalla interrumpida, espadas en alto","g":"Dispositivo narrativo real","t":"Quijote, 1605"},{"w":"La memoria reconstructiva","gen":"Hallazgo","n":"Una palabra cambia un recuerdo","g":"Psicología cognitiva","t":"Loftus y Palmer, 1974"},{"w":"Los recuerdos de flash","gen":"Hallazgo con matización","n":"Nítidos pero a menudo falsos","g":"Psicología de la memoria","t":"Brown y Kulik, 1977; Neisser y Harsch, 1992"},{"w":"El reloj del relato","gen":"Herramienta práctica","n":"El orden, la duración, lo que el lector sabe","g":"Herramienta de esta casa","t":"Etapa 7"}];
const completeTaskDB=[{"s":"Genette separa el tiempo de la historia del tiempo del ___.","opts":["relato","personaje","lector"],"ans":"relato"},{"s":"Shklovski y Tomashevski separan la fábula de la ___.","opts":["trama","pausa","escena"],"ans":"trama"},{"s":"El suspense, según Hitchcock, le da al público lo que el ___ no sabe.","opts":["personaje","director","crítico"],"ans":"personaje"},{"s":"Sternberg describe tres relojes: suspense, curiosidad y ___.","opts":["sorpresa","elipsis","fábula"],"ans":"sorpresa"},{"s":"Iser llama huecos a lo que el relato ___.","opts":["calla","repite","aclara"],"ans":"calla"},{"s":"Horacio prefería el in medias res al comienzo ___.","opts":["ab ovo","in extremis","de facto"],"ans":"ab ovo"},{"s":"El Quijote deja las espadas en alto al final de un ___.","opts":["capítulo","tomo","prólogo"],"ans":"capítulo"},{"s":"El reloj del relato tiene tres ___.","opts":["casillas","escenas","autores"],"ans":"casillas"}];
const explainQuestions=[{"q":"Explica la distinción entre el tiempo de la historia y el tiempo del relato, según Gérard Genette (1972), y sus tres ejes.","ans":"Gérard Genette, en «Figures III» (1972), separa el tiempo de la historia (lo que pasó, en su orden cronológico real) del tiempo del relato (cómo se cuenta), y describe tres ejes en los que ambos pueden diferir: el orden (las anacronías, saltos atrás o adelante), la duración (las velocidades del relato: escena, resumen, elipsis y pausa) y la frecuencia (contar una vez lo que pasó una vez, o una vez lo que pasó muchas veces). Confundir estos tres ejes con el propio contenido de la historia es el error de fondo que esta etapa desarma."},{"q":"Explica la diferencia entre la fábula y la trama, según los formalistas rusos Viktor Shklovski (1917) y Boris Tomashevski (1925).","ans":"Los formalistas rusos distinguen la fábula, los hechos de una historia en el orden en que de verdad ocurrieron, de la trama o sujet, el orden en que el relato decide contarlos, casi siempre distinto del orden real. Shklovski, en «El arte como artificio» (1917), añade el concepto del extrañamiento (ostranenie): el arte hace extraño lo habitual para que se vuelva a ver de verdad, y reordenar el tiempo es una de las maneras más antiguas de lograrlo. Boris Tomashevski, en «Teoría de la literatura» (1925), sistematiza esta distinción dentro de la escuela formalista."},{"q":"Explica, con el ejemplo de la bomba bajo la mesa, la diferencia entre el suspense y la sorpresa, según Hitchcock (vía Truffaut, 1966).","ans":"Alfred Hitchcock, en la entrevista que le hizo François Truffaut, publicada en 1966, explica que el suspense se crea dándole al público una información que los personajes no tienen: si el espectador sabe que hay una bomba bajo la mesa y cuánto falta para que estalle, una conversación aburrida se vuelve insoportable de ver. La sorpresa, en cambio, es un susto de pocos segundos, sin ningún aviso previo. El propio Hitchcock reconoce el límite de su regla: en «Psicosis» (1960), usó la sorpresa a propósito en la escena de la ducha, porque quería un golpe que nadie viera venir."},{"q":"Explica la herramienta de los tres relojes de Meir Sternberg (1978), y cómo formaliza la intuición de Hitchcock.","ans":"Meir Sternberg, en «Expositional Modes and Temporal Ordering in Fiction» (1978), da el marco académico detrás de la intuición de Hitchcock: el interés narrativo se mueve por lo que el lector sabe y cuándo lo sabe, y describe tres relojes distintos. El suspense mira hacia un futuro incierto (¿qué va a pasar?); la curiosidad mira hacia un pasado que se oculta (¿qué pasó?); y la sorpresa es una recolocación súbita de lo que se creía saber. Los tres pueden convivir en un mismo relato, según qué se le muestre al lector y en qué momento."},{"q":"Explica el precepto del in medias res, de Horacio (hacia el año 18 a.C.), y por qué es la fila más vieja de la tabla madre de esta etapa.","ans":"Horacio, en su «Arte poética» (hacia el año 18 antes de Cristo), elogiaba a Homero por lanzar al oyente in medias res, en mitad de las cosas, en vez de empezar ab ovo, desde el huevo, el principio absoluto de la historia. Es la fila más vieja de la tabla madre de esta etapa, y demuestra que alterar el orden en que se cuenta una historia no es una moda reciente de guion o de cine, sino la técnica más antigua y comprobable del oficio de contar, con más de dos mil años de uso documentado."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la herramienta ilustrada en cada oración. Escribe al lado de qué herramienta se trata.','<strong>Ejemplo:</strong> El Quijote corta una batalla con las espadas en alto, al final de un capítulo. → <span style="color:var(--jade);font-weight:700;">El corte de suspense del Quijote (1605)</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
