const evalTFBank=[{"q":"La regla de oro de esta materia exige que toda herramienta se cite con autor y año.","a":true},{"q":"Gérard Genette publicó «Figures III» en 1972.","a":true},{"q":"Fábula y trama son la misma cosa, con dos nombres distintos.","a":false},{"q":"El suspense y la sorpresa son mecanismos opuestos, según Hitchcock (vía Truffaut, 1966).","a":true},{"q":"Hitchcock nunca usó la sorpresa en ninguna de sus películas.","a":false},{"q":"Meir Sternberg describe tres relojes del interés narrativo: suspense, curiosidad y sorpresa.","a":true},{"q":"Wolfgang Iser publicó «El acto de leer» en 1976.","a":true},{"q":"Según Iser, la elipsis es información perdida para siempre.","a":false},{"q":"Horacio elogiaba a Homero por empezar sus historias in medias res.","a":true},{"q":"Horacio escribió su «Arte poética» en el siglo veinte.","a":false},{"q":"El Quijote (1605) interrumpe una batalla con las espadas en alto, al final de un capítulo.","a":true},{"q":"Viktor Shklovski publicó «El arte como artificio» en 1917.","a":true},{"q":"Boris Tomashevski publicó «Teoría de la literatura» en 1925.","a":true},{"q":"El reloj del relato tiene tres casillas: el orden, la duración, y lo que el lector sabe y cuándo.","a":true},{"q":"Elizabeth Loftus y John Palmer demostraron, en 1974, que la memoria es una grabación fija e infalible.","a":false}];
const evalMCBank=[{"q":"¿Qué separa Gérard Genette en «Figures III» (1972)?","o":["a) El tono y el ritmo","b) El tiempo de la historia y el tiempo del relato","c) Mostrar y contar","d) Suspense y sorpresa"],"a":1},{"q":"¿Cuáles son los tres ejes del tiempo del relato, según Genette (1972)?","o":["a) Fábula, trama y sujet","b) Pasado, presente y futuro","c) Orden, duración y frecuencia","d) Escena, resumen y pausa, sin más"],"a":2},{"q":"¿Qué distinguen los formalistas rusos Shklovski (1917) y Tomashevski (1925)?","o":["a) La fábula de la trama","b) El suspense de la sorpresa","c) La escena de la pausa","d) El resumen de la elipsis"],"a":0},{"q":"¿Qué es el extrañamiento (ostranenie), de Viktor Shklovski (1917)?","o":["a) Hacer extraño lo habitual, para que se vuelva a ver","b) Contar en tercera persona","c) Un tipo de rima","d) El resumen de una escena"],"a":0},{"q":"Según Hitchcock (vía Truffaut, 1966), ¿qué crea el suspense?","o":["a) Darle al público una información que los personajes no tienen","b) Ocultarle todo al público","c) Sorprender sin aviso","d) Repetir la misma escena"],"a":0},{"q":"¿En qué película usó Hitchcock la sorpresa a propósito, según su propia entrevista?","o":["a) «Vértigo» (1958)","b) «Los pájaros» (1963)","c) «Psicosis» (1960)","d) «La ventana indiscreta» (1954)"],"a":2},{"q":"¿Cuáles son los tres relojes del interés, de Meir Sternberg (1978)?","o":["a) Orden, duración y frecuencia","b) Fábula, trama y sujet","c) Suspense, curiosidad y sorpresa","d) Escena, resumen y elipsis"],"a":2},{"q":"¿Qué es la elipsis, los huecos (Leerstellen), según Wolfgang Iser (1976)?","o":["a) Trabajo que el lector hace, rellenando lo que no se cuenta","b) Un error del narrador","c) Información perdida para siempre","d) Una regla que nunca debe romperse"],"a":0},{"q":"¿Qué precepto describe Horacio en su «Arte poética» (hacia el 18 a.C.)?","o":["a) Empezar siempre ab ovo","b) Repetir la escena tres veces","c) Empezar in medias res, en mitad de las cosas","d) Nunca resumir nada"],"a":2},{"q":"¿Qué hace el narrador del «Quijote» (1605) con una batalla en su momento más alto?","o":["a) La cuenta completa sin cortes","b) La interrumpe con las espadas en alto","c) La omite del todo","d) La cuenta dos veces"],"a":1},{"q":"¿Cuáles son las tres casillas del reloj del relato, la herramienta de esta etapa?","o":["a) Título, fecha y lugar","b) Presupuesto, elenco y locación","c) Género, tono y duración","d) El orden, la duración, y lo que el lector sabe y cuándo"],"a":3},{"q":"¿Qué demostró el experimento de Elizabeth Loftus y John Palmer (1974)?","o":["a) Que la memoria es una grabación exacta","b) Que una palabra en una pregunta puede cambiar un recuerdo","c) Que nadie recuerda accidentes de auto","d) Que la memoria mejora con la edad"],"a":1},{"q":"¿Qué nombraron Roger Brown y James Kulik en 1977?","o":["a) La memoria reconstructiva","b) El estilo indirecto libre","c) La tarea de la falsa creencia","d) Los recuerdos de flash (flashbulb memories)"],"a":3},{"q":"¿Qué mostraron Ulric Neisser y Nicole Harsch (1992), con el caso del Challenger?","o":["a) Que nadie recordó la explosión","b) Que la NASA ocultó el accidente","c) Que los recuerdos de flash nunca fallan","d) Que los recuerdos nítidos y seguros a menudo son falsos"],"a":3},{"q":"¿Por qué «suspense» no es lo mismo que «sorpresa»?","o":["a) Porque la sorpresa no existe en el cine","b) Porque el suspense necesita que el público sepa algo que el personaje no sabe, y la sorpresa llega sin aviso","c) Porque el suspense es siempre mejor","d) Porque Hitchcock las prohibió por igual"],"a":1}];
const evalCPBank=[{"q":"Genette separa el tiempo de la historia del tiempo del ___.","a":"relato"},{"q":"Genette publicó «Figures III» en ___.","a":"1972"},{"q":"Shklovski y Tomashevski separan la fábula de la ___.","a":"trama"},{"q":"Shklovski publicó «El arte como artificio» en ___.","a":"1917"},{"q":"Tomashevski publicó «Teoría de la literatura» en ___.","a":"1925"},{"q":"El suspense le da al público un dato que el ___ no tiene.","a":"personaje"},{"q":"Hitchcock explicó la bomba bajo la mesa en la entrevista publicada por Truffaut en ___.","a":"1966"},{"q":"Sternberg describe tres relojes: suspense, curiosidad y ___.","a":"sorpresa"},{"q":"Sternberg publicó su modelo de los tres relojes en ___.","a":"1978"},{"q":"Iser llama huecos a lo que el relato ___.","a":"calla"},{"q":"Iser publicó «El acto de leer» en ___.","a":"1976"},{"q":"Horacio prefería el in medias res al comienzo ___.","a":"ab ovo"},{"q":"El Quijote deja las espadas en alto al final de un ___.","a":"capítulo"},{"q":"Loftus y Palmer publicaron su experimento del choque de autos en ___.","a":"1974"},{"q":"El reloj del relato tiene tres ___.","a":"casillas"}];
const evalPRBank=[{"term":"El tiempo del relato","def":"Orden, duración y frecuencia con que se cuenta una historia (Genette, 1972)"},{"term":"La fábula","def":"Los hechos de una historia, en el orden en que de verdad ocurrieron"},{"term":"La trama (el sujet)","def":"El orden en que el relato cuenta esos mismos hechos (Shklovski, 1917; Tomashevski, 1925)"},{"term":"El extrañamiento (ostranenie)","def":"Hacer extraño lo habitual, para que se vuelva a ver de verdad (Shklovski, 1917)"},{"term":"La analepsis y la prolepsis","def":"El salto atrás y el salto adelante en el tiempo del relato (Genette, 1972)"},{"term":"El suspense","def":"Darle al público una información que los personajes no tienen (Hitchcock, vía Truffaut, 1966)"},{"term":"La sorpresa","def":"Un susto breve, sin ningún aviso previo al público"},{"term":"Los tres relojes","def":"Suspense, curiosidad y sorpresa, según Meir Sternberg (1978)"},{"term":"La elipsis y los huecos","def":"Lo que el relato calla, y que el lector rellena (Iser, 1976)"},{"term":"In medias res","def":"Empezar la historia en mitad de las cosas (Horacio, hacia el 18 a.C.)"},{"term":"Ab ovo","def":"Empezar la historia desde su principio absoluto"},{"term":"El corte de suspense del Quijote","def":"La batalla interrumpida con las espadas en alto, al final de un capítulo (1605)"},{"term":"El reloj del relato","def":"La herramienta de esta etapa: el orden, la duración, y lo que el lector sabe y cuándo"},{"term":"La memoria reconstructiva","def":"Una palabra cambia el recuerdo de un hecho (Loftus y Palmer, 1974)"},{"term":"Los recuerdos de flash","def":"Nítidos pero a menudo falsos (Brown y Kulik, 1977; Neisser y Harsch, 1992)"}];
function genEval(){sfx('click');_evalFormaSelector();const _selF=document.getElementById('evalFormaSel');if(_selF&&parseInt(_selF.value,10))evalFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_selF.value,10)));const cf=evalFormNum;const rng=_evalRng(cf);window._currentEvalForm=cf;evalFormNum=(evalFormNum%EVAL_FORMAS)+1;_evalFormaSelector();saveProgress();document.getElementById('eval-screen-title').textContent=`🎓 Evaluación Final · Forma ${cf} · El tiempo del relato · Ruta del Hilo que Tira`;evalAnsVisible=false;const out=document.getElementById('evalOut');out.innerHTML='';const bar=document.createElement('div');bar.className='eval-score-bar';bar.innerHTML=`<div><div class="esb-title">📊 Distribución de puntaje · 100 puntos</div><div class="esb-dist">Cada sección vale 25 puntos (5 preguntas × 5 pts)</div></div><div style="display:flex;gap:0.4rem;flex-wrap:wrap;"><span class="eval-score-pill esp-cp">Completar 25 pts</span><span class="eval-score-pill esp-tf">V/F 25 pts</span><span class="eval-score-pill esp-mc">Selección 25 pts</span><span class="eval-score-pill esp-pr">Pareados 25 pts</span></div>`;out.appendChild(bar);const cpItems=_pickF(evalCPBank,5,rng);const s1=document.createElement('div');s1.innerHTML='<div class="eval-section-title">I. Completar el espacio <span class="eval-pts">25 pts · 5 pts c/u</span></div>';cpItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='cp';d.dataset.evalIndex=i;const qHtml=item.q.replace('___',`<input class="eval-cp-input" type="text" data-cp="${i}" autocomplete="off">`);d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+1}</span><span class="eval-q-text">${qHtml}</span></div><div class="eval-answer">${item.a}</div><div class="eval-item-feedback" id="evalFbCp${i}" aria-live="polite"></div>`;s1.appendChild(d);});out.appendChild(s1);const tfItems=_pickF(evalTFBank,5,rng);const s2=document.createElement('div');s2.innerHTML='<div class="eval-section-title">II. Verdadero o Falso <span class="eval-pts">25 pts · 5 pts c/u</span></div>';tfItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='tf';d.dataset.evalIndex=i;d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+6}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-tf-opts"><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="true"> Verdadero</label><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="false"> Falso</label></div><div class="eval-answer">${item.a?'Verdadero':'Falso'}</div><div class="eval-item-feedback" id="evalFbTf${i}" aria-live="polite"></div>`;s2.appendChild(d);});out.appendChild(s2);const mcItems=_pickF(evalMCBank,5,rng);const s3=document.createElement('div');s3.innerHTML='<div class="eval-section-title">III. Selección Múltiple <span class="eval-pts">25 pts · 5 pts c/u</span></div>';mcItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='mc';d.dataset.evalIndex=i;const optsHtml=item.o.map((op,oi)=>`<label class="eval-mc-opt"><input type="radio" name="mc${i}" value="${oi}"> ${op}</label>`).join('');d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+11}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-mc-opts">${optsHtml}</div><div class="eval-answer">${item.o[item.a]}</div><div class="eval-item-feedback" id="evalFbMc${i}" aria-live="polite"></div>`;s3.appendChild(d);});out.appendChild(s3);const prItems=_pickF(evalPRBank,5,rng);let shuffledDefs=_shuffleF(prItems,rng);let _prTries=0;while(shuffledDefs.some((df,ix)=>df.def===prItems[ix].def)&&_prTries<20){shuffledDefs=_shuffleF(shuffledDefs,rng);_prTries++;}const letters=['A','B','C','D','E'];const s4=document.createElement('div');s4.innerHTML='<div class="eval-section-title">IV. Términos Pareados <span class="eval-pts">25 pts · 5 pts c/u</span></div>';const matchCard=document.createElement('div');matchCard.className='eval-item';let colLeft='<div class="eval-match-col"><h4>📌 Términos</h4>';prItems.forEach((item,i)=>{colLeft+=`<div class="eval-match-item"><span class="eval-match-letter">${i+16}.</span> <select class="eval-match-select" data-pr="${i}" aria-label="Respuesta pareada ${i+16}"><option value="">?</option>${letters.map(l=>`<option value="${l}">${l}</option>`).join('')}</select> ${item.term}</div>`;});colLeft+='</div>';let colRight='<div class="eval-match-col"><h4>🔑 Definiciones</h4>';shuffledDefs.forEach((item,i)=>{colRight+=`<div class="eval-match-item"><span class="eval-match-letter">${letters[i]}.</span> ${item.def}</div>`;});colRight+='</div>';const ansKey=prItems.map((item,i)=>{const letter=letters[shuffledDefs.findIndex(d=>d.def===item.def)];return`${i+16}→${letter}`;}).join(' · ');matchCard.innerHTML=`<div class="eval-match-grid">${colLeft}${colRight}</div><div class="eval-answer" style="display:none;">${ansKey}</div><div class="eval-item-feedback" id="evalFbPr" aria-live="polite"></div>`;s4.appendChild(matchCard);out.appendChild(s4);window._evalPrintData={tf:tfItems,mc:mcItems,cp:cpItems,pr:{terms:prItems,shuffledDefs,letters}};const autoPanel=document.createElement('div');autoPanel.id='evalAutoResult';autoPanel.className='eval-auto-result';autoPanel.innerHTML='<strong>🧮 Evaluación interactiva:</strong> responde en pantalla y presiona <em>Calificar prueba</em>. La impresión conserva el formato original sin respuestas digitadas.';out.appendChild(autoPanel);fin('s-evaluacion');}
function toggleEvalAns(){evalAnsVisible=!evalAnsVisible;document.querySelectorAll('#evalOut .eval-answer').forEach(el=>el.style.display=evalAnsVisible?'block':'none');sfx('click');}
function normalizeEvalAnswer(v){return(v||'').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ').replace(/[()]/g,'').trim();}
function isCpCorrect(student,expected){const s=normalizeEvalAnswer(student);const e=normalizeEvalAnswer(expected);if(!s)return false;const variants=new Set([e]);if(e.includes(' '))e.split(' ').forEach(x=>x&&variants.add(x));return variants.has(s)||e.replace(/[^a-z0-9]/g,'')===s.replace(/[^a-z0-9]/g,'');}
function setEvalFeedback(id,ok,msg){const el=document.getElementById(id);if(!el)return;el.textContent=msg;el.className='eval-item-feedback '+(ok?'eval-ok':'eval-no');}
function gradeEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const d=window._evalPrintData;let total=0;const detail={cp:0,tf:0,mc:0,pr:0};d.cp.forEach((it,i)=>{const input=document.querySelector(`[data-cp="${i}"]`);const ok=isCpCorrect(input?input.value:'',it.a);if(input){input.classList.toggle('eval-input-ok',ok);input.classList.toggle('eval-input-no',!ok);}if(ok){detail.cp++;total+=5;}setEvalFeedback('evalFbCp'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.a);});d.tf.forEach((it,i)=>{const selected=document.querySelector(`input[name="tf${i}"]:checked`);const ok=!!selected&&(selected.value==='true')===it.a;if(ok){detail.tf++;total+=5;}setEvalFeedback('evalFbTf'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+(it.a?'Verdadero':'Falso'));});d.mc.forEach((it,i)=>{const selected=document.querySelector(`input[name="mc${i}"]:checked`);const ok=!!selected&&Number(selected.value)===it.a;if(ok){detail.mc++;total+=5;}setEvalFeedback('evalFbMc'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.o[it.a]);});const expectedLetters=d.pr.terms.map(it=>d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)]);expectedLetters.forEach((letter,i)=>{const sel=document.querySelector(`[data-pr="${i}"]`);const ok=!!sel&&sel.value===letter;if(sel){sel.classList.toggle('eval-input-ok',ok);sel.classList.toggle('eval-input-no',!ok);}if(ok){detail.pr++;total+=5;}});const prMsg=`Pareados: ${detail.pr}/5 correctos. ${detail.pr===5?'Excelente. +25 pts':'Clave: '+expectedLetters.map((l,i)=>(i+16)+'→'+l).join(' · ')}`;setEvalFeedback('evalFbPr',detail.pr===5,prMsg);const result=document.getElementById('evalAutoResult');if(result){result.className='eval-auto-result '+(total>=70?'eval-auto-pass':'eval-auto-risk');result.innerHTML=`<strong>Resultado automático: ${total}/100 puntos</strong><br><span>Completar: ${detail.cp*5}/25 · V/F: ${detail.tf*5}/25 · Selección: ${detail.mc*5}/25 · Pareados: ${detail.pr*5}/25</span><br><em>Este resultado es solo para revisión en pantalla; la impresión conserva el formato limpio para papel.</em>`;}if(total>=70){pts(8);showToast('🎯 Evaluación calificada: '+total+'/100');}else showToast('🧮 Evaluación calificada: '+total+'/100. Revisa las respuestas marcadas.');}
function printEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const forma=window._currentEvalForm||1;const d=window._evalPrintData;let s1=`<div class="sec-title"><span>I. Completar el espacio</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.cp.forEach((it,i)=>{const q=it.q.replace('___','<span class="cp-blank"></span>');s1+=`<div class="cp-row"><span class="qn">${i+1}.</span><span class="cp-text">${q}</span></div>`;});let s2=`<div class="sec-title"><span>II. Verdadero o Falso</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.tf.forEach((it,i)=>{s2+=`<div class="tf-row"><span class="qn">${i+6}.</span><span class="tf-blank"></span><span class="tf-text">${it.q}</span></div>`;});let s3=`<div class="sec-title"><span>III. Selección Múltiple</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="mc-grid">`;d.mc.forEach((it,i)=>{const opts=it.o.map((op,oi)=>`<label class="mc-opt"><input type="radio" name="mcp${i}"> ${op}</label>`).join('');s3+=`<div class="mc-item"><div class="mc-q"><span class="qn">${i+11}.</span><span>${it.q}</span></div><div class="mc-opts">${opts}</div></div>`;});s3+=`</div>`;let colL='<div class="pr-col"><div class="pr-head">📌 Términos</div>';d.pr.terms.forEach((it,i)=>{colL+=`<div class="pr-item"><span class="pr-num">${i+16}.</span><span class="pr-line"></span>${it.term}</div>`;});colL+='</div>';let colR='<div class="pr-col"><div class="pr-head">🔑 Definiciones</div>';d.pr.shuffledDefs.forEach((it,i)=>{colR+=`<div class="pr-item"><span class="pr-num">${d.pr.letters[i]}.</span>${it.def}</div>`;});colR+='</div>';let s4=`<div class="pr-section"><div class="sec-title"><span>IV. Términos Pareados</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="pr-grid">${colL}${colR}</div></div>`;let pR='';pR+=`<div class="p-sec"><div class="p-ttl">I. Completar</div><table class="p-tbl">`;d.cp.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+1}.</td><td class="pa">${it.a}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">II. V o F</div><table class="p-tbl">`;d.tf.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+6}.</td><td class="pa">${it.a?'V':'F'}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">III. Selección</div><table class="p-tbl">`;d.mc.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+11}.</td><td class="pa">${it.o[it.a]}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">IV. Pareados</div><table class="p-tbl">`;d.pr.terms.forEach((it,i)=>{const l=d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)];pR+=`<tr><td class="pn">${i+16}.</td><td class="pa">${i+16}→${l}</td></tr>`;});pR+=`</table></div>`;const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Evaluación El tiempo del relato · Ruta del Hilo que Tira · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.12rem 0.4rem;margin:0.22rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #be185d;background:#fce7f3;color:#be185d;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#be185d;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:58px;border-bottom:1.5px solid #be185d;height:12px;}.obt-pct{white-space:nowrap;}.qn{font-weight:700;min-width:22px;flex-shrink:0;}.tf-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.tf-blank{display:inline-block;min-width:40px;border-bottom:1.5px solid #111;flex-shrink:0;margin:0 0.18rem;}.tf-text{flex:1;}.mc-item{border:1px solid #ddd;border-radius:4px;padding:0.14rem 0.35rem;margin-bottom:0.1rem;break-inside:avoid;page-break-inside:avoid;}.mc-q{font-size:10.5pt;line-height:1.3;display:flex;gap:0.28rem;margin-bottom:0.07rem;}.mc-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.1rem 0.5rem;}.mc-opts{display:grid;grid-template-columns:repeat(4,1fr);gap:0.04rem 0.15rem;margin-left:0.8rem;}.mc-opt{font-size:9pt;display:flex;align-items:center;gap:0.15rem;}.mc-opt input{width:10px;height:10px;flex-shrink:0;}.cp-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.cp-text{flex:1;}.cp-blank{display:inline-block;min-width:150px;border-bottom:1.5px solid #111;margin:0 0.12rem;}.pr-section{margin-top:0.1rem;}.pr-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.08rem 0.4rem;margin-top:0.08rem;}.pr-head{font-size:9pt;font-weight:700;color:#555;margin-bottom:0.1rem;}.pr-item{font-size:10.5pt;padding:0.1rem 0.28rem;background:#fce7f3;border-radius:3px;margin-bottom:0.07rem;display:flex;align-items:center;gap:0.2rem;line-height:1.2;break-inside:avoid;page-break-inside:avoid;}.pr-num{font-weight:700;color:#be185d;min-width:19px;flex-shrink:0;}.pr-line{display:inline-block;min-width:19px;border-bottom:1.5px solid #111;margin-right:0.14rem;flex-shrink:0;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.22rem;padding:0.15rem 0;page-break-before:avoid;break-before:avoid;color:#be185d;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #be185d;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.25rem 0.4rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.15rem;}.p-tbl{width:100%;border-collapse:collapse;font-size:7.5pt;}.p-tbl tr{border-bottom:1px dotted #ddd;}.p-tbl td{padding:0.07rem 0.12rem;vertical-align:top;}.pn{font-weight:700;width:16px;color:#555;}.pa{color:#007a00;font-weight:600;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Final · El tiempo del relato · Ruta del Hilo que Tira · Etapa 7</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Instituto:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · Cada respuesta vale 5 puntos</p></div>${s1}${s2}${s3}${s4}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100%</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Evaluación Final · El tiempo del relato · Ruta del Hilo que Tira · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 4 secciones × 5 preguntas × 5 pts c/u</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;const win=window.open('','_blank','');if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);}

