// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"hacia el 18 a.C.","icon":"🏛️","label":"Horacio y el in medias res","text":"Horacio escribe su «Arte poética» (Ars Poetica), y elogia a Homero por lanzar al oyente in medias res, en mitad de las cosas, en vez de empezar ab ovo, desde el principio absoluto. <strong>Por qué importa aquí:</strong> es la fecha más vieja de la tabla madre, y muestra que alterar el orden del relato es la técnica más antigua del oficio."},{"y":"1917","icon":"👀","label":"Shklovski y el extrañamiento","text":"Viktor Shklovski publica «El arte como artificio», donde acuña el extrañamiento (ostranenie) y sienta las bases de la distinción entre fábula y trama. <strong>Por qué importa aquí:</strong> es el origen de la escuela formalista rusa, que separa los hechos de su orden en el relato."},{"y":"1925","icon":"🧩","label":"Tomashevski sistematiza fábula y trama","text":"Boris Tomashevski publica «Teoría de la literatura», donde sistematiza la distinción entre fábula (los hechos en su orden real) y trama o sujet (el orden en que se cuentan). <strong>Por qué importa aquí:</strong> completa, dentro de la misma escuela, la distinción fundacional de esta etapa."},{"y":"1966","icon":"💣","label":"Hitchcock, vía Truffaut, y la bomba bajo la mesa","text":"Se publica «El cine según Hitchcock», la larga entrevista de François Truffaut a Alfred Hitchcock, donde explica la diferencia entre suspense y sorpresa con el ejemplo de la bomba bajo la mesa. <strong>Por qué importa aquí:</strong> es la distinción más citada de toda la etapa."},{"y":"1972","icon":"🕰️","label":"Genette separa orden, duración y frecuencia","text":"Gérard Genette publica «Figures III», donde separa el tiempo de la historia del tiempo del relato en tres ejes: orden, duración y frecuencia. <strong>Por qué importa aquí:</strong> es la herramienta central de toda la etapa."},{"y":"1976","icon":"🕳️","label":"Iser y los huecos que llena el lector","text":"Wolfgang Iser publica «El acto de leer» (Der Akt des Lesens), donde describe la elipsis como Leerstellen, huecos que el lector rellena con su propio trabajo. <strong>Por qué importa aquí:</strong> explica por qué saltar bien es tan importante como mostrar bien."},{"y":"1978","icon":"⏰","label":"Sternberg y los tres relojes del interés","text":"Meir Sternberg publica «Expositional Modes and Temporal Ordering in Fiction», donde formaliza, con marco académico, la intuición de Hitchcock: suspense, curiosidad y sorpresa, según lo que el lector sabe y cuándo. <strong>Por qué importa aquí:</strong> es el puente entre la poética de un cineasta y la teoría literaria."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: «HAY QUE SORPRENDER AL LECTOR EN CADA ESCENA» ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(seAplicaReloj){sfx(seAplicaReloj?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(seAplicaReloj){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🕰️</span><span class="ms-text"><strong>Se aplicó el reloj del relato:</strong> se identificaron los saltos que no revelaban nada, se reordenaron dos escenas en orden cronológico, y se dejó solo un salto in medias res al inicio, declarado a propósito.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">✂️</span><span class="ms-text"><strong>Quedó apuntada la razón del cambio:</strong> «sorprender no es lo mismo que interesar», para que la próxima vez no haga falta discutirlo desde cero.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">📤</span><span class="ms-text"><strong>Se publicó tal cual:</strong> el video saltaba de escena en escena sin ningún criterio, y varias personas que lo vieron después dijeron que no habían entendido qué pasó primero.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🕰️</span><span class="ms-text"><strong>Confundir «mantener el interés» con «sorprender siempre»</strong> es exactamente el error que esta etapa señala: lo que sostiene el interés no es el desorden en sí, es que el lector sepa algo (o no sepa algo) en el momento exacto en que eso importa.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
// Las llaves del laboratorio (esperado, paradoja, utilidad, ruina) se HEREDAN
// del molde a propósito: los botones del HTML llaman labShowParte('esperado')
// etc., y renombrarlas aquí sin tocar ese archivo rompería el laboratorio en
// silencio. El nombre visible sale de cada «nombre», nunca de la llave. En
// esta etapa el reparto es: esperado = El orden (fábula y trama), paradoja =
// La duración (escena, resumen, elipsis), utilidad = El suspense (lo que el
// lector sabe), ruina = El desorden como muletilla.
const parteData={"esperado":{"nombre":"El orden (fábula y trama)","icon":"🔀","estructura":{"title":"Qué es","info":"• El ORDEN: ¿en qué orden ocurrió (la fábula) y en qué orden se cuenta (la trama)?<br>• Distinción fundacional de los formalistas rusos, <strong>Viktor Shklovski (1917)</strong> y <strong>Boris Tomashevski (1925)</strong><br>• Genette (1972) llama anacronía a cualquier salto: analepsis (atrás) o prolepsis (adelante)<br>• El orden NO dice, por sí solo, si el relato es bueno o malo"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿qué pasó primero, en la realidad de la historia?<br>• Se compara con el orden en que el relato lo cuenta de verdad<br>• Se identifica cada salto: ¿es analepsis o prolepsis, y para qué sirve?<br>• Se anota en la primera casilla del reloj del relato"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que el orden cronológico es siempre el más claro<br>• En confundir el salto atrás que revela algo nuevo con el que solo explica<br>• En olvidar el año de Shklovski (1917) o Tomashevski (1925) al citar la distinción<br>• En tratar in medias res como un invento moderno del cine"},"cuidados":{"title":"En esta casa","info":"• Todo relato de esta casa identifica primero su fábula, antes de decidir su trama<br>• Se declara siempre «Shklovski, 1917» o «Tomashevski, 1925» al lado, no «así se cuenta siempre»<br>• Se usa como primer paso del protocolo, antes de preguntar la duración<br>• Y se recuerda que el orden es una elección, no un accidente"}},"paradoja":{"nombre":"La duración (escena, resumen, elipsis)","icon":"⏱️","estructura":{"title":"Qué es","info":"• La DURACIÓN: las velocidades del relato, según <strong>Genette (1972)</strong><br>• Escena: tiempo real. Resumen: se acelera. Elipsis: se salta. Pausa: se detiene el tiempo de la historia<br>• Wolfgang Iser (1976) explica que la elipsis no es ausencia, es trabajo del lector<br>• Es la que se confunde con «contarlo todo por igual»"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿qué se estira en escena, qué se resume, y qué se salta?<br>• Se busca si algo se cuenta minuto a minuto sin necesitarlo<br>• Se comprueba si una elipsis deja un hueco confuso, o uno que el lector llena sin esfuerzo<br>• Se anota en la segunda casilla del reloj del relato"},"enfermedades":{"title":"Dónde se cae","info":"• En estirar a tiempo real algo que no lo necesita<br>• En creer que toda elipsis es un descuido que hay que rellenar con más texto<br>• En repetir (frecuencia) lo que ya se dijo, sin ninguna razón<br>• En citar a Genette sin mencionar el matiz de Iser sobre los huecos"},"cuidados":{"title":"En esta casa","info":"• Todo video largo revisa qué gira (se estira) y qué no (se resume o se salta)<br>• Se declara «Genette, 1972» y, si hace falta el matiz fino, «Iser, 1976»<br>• Se usa como diagnóstico: si algo aburre, puede que sobre duración<br>• Y se recuerda que una elipsis bien puesta no necesita explicarse"}},"utilidad":{"nombre":"El suspense (lo que el lector sabe)","icon":"💣","estructura":{"title":"Qué es","info":"• LO QUE EL LECTOR SABE, Y CUÁNDO: la tercera casilla del reloj del relato<br>• <strong>Alfred Hitchcock, vía François Truffaut (1966)</strong>: el suspense le da al público un dato que el personaje no tiene<br>• <strong>Meir Sternberg (1978)</strong>: tres relojes, suspense, curiosidad y sorpresa<br>• El caso comprobable: el <strong>Quijote (1605)</strong>, que corta una batalla con las espadas en alto"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿el público sabe algo que el personaje no sabe?<br>• Se busca si el interés mira al futuro (suspense) o al pasado (curiosidad)<br>• Se comprueba si un giro es una sorpresa real, o si ya estaba anunciado<br>• Se anota en la tercera casilla, aunque a veces sea una mezcla de los tres relojes"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que suspense y sorpresa son la misma cosa<br>• En esconder un dato que, revelado antes, generaría más tensión, no menos<br>• En dejar un salto sin ninguna función que lo sostenga<br>• En olvidar que el propio Hitchcock usó la sorpresa a propósito en «Psicosis» (1960)"},"cuidados":{"title":"En esta casa","info":"• Todo video de la casa declara si busca suspense, curiosidad o sorpresa, a propósito<br>• Se declara «Hitchcock, vía Truffaut, 1966» junto al ejemplo de la bomba bajo la mesa<br>• Se usa el corte del Quijote (1605) como modelo de suspense honrado<br>• Y se recuerda que ningún relato necesita elegir uno solo de los tres relojes"}},"ruina":{"nombre":"El desorden como muletilla","icon":"🌀","estructura":{"title":"Qué es","info":"• Contar fuera de orden SIN razón, solo porque «así se ve más interesante»<br>• Es el vicio que la <strong>OBJECIÓN</strong> del careo de esta etapa señala con más fuerza<br>• Un salto atrás que solo explica, sin revelar nada nuevo, es el ejemplo más común<br>• No es lo mismo que la anacronía con función (Genette, 1972)"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿este salto en el tiempo revela algo que el lector no sabía?<br>• Si solo repite o explica algo ya sabido, es una muletilla, no una elección<br>• Se compara con el orden cronológico: ¿el orden llano contaría lo mismo, mejor?<br>• Se decide si el salto se ganó su lugar, o solo está de moda"},"enfermedades":{"title":"Dónde se cae","info":"• En reordenar un relato sin ninguna razón, solo por parecer sofisticado<br>• En usar un flashback que únicamente «explica» una escena anterior<br>• En creer que el desorden siempre acerca al lector, sin comprobarlo<br>• En olvidar que la claridad cronológica también es una elección legítima"},"cuidados":{"title":"En esta casa","info":"• Todo salto en el tiempo, en esta casa, se justifica por escrito antes de usarse<br>• Se pregunta siempre: ¿qué revela este salto que el orden llano no revelaría?<br>• Se prefiere el orden llano cuando el salto no aporta nada nuevo<br>• Y se recuerda la regla del careo: un salto debe ganarse su lugar"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

