const lectAnalisisBank=[
{q:'Explica por qué Práxedes siente curiosidad y no suspense al escuchar su vida contada al revés, y relaciona tu respuesta con la distinción de Sternberg (1978) entre estos dos mecanismos.',guia:'Se espera que el lector explique que el suspense necesita un futuro incierto (¿qué va a pasar?), y Práxedes ya conoce su propio final, la mano estirada y vacía, desde la primera página que el archivero le lee; por eso lo que siente, según Meir Sternberg (1978), es curiosidad: el interés por un pasado que se oculta y se va revelando hacia atrás, hoja por hoja, hasta la comadrona bajo la lluvia. El cuento ilustra con un solo personaje la diferencia entre los dos relojes del interés que Sternberg describe: uno mira hacia el futuro que no se conoce, el otro hacia el pasado que todavía no se entiende.',t:'Borges'},
{q:'Explica qué relación hay entre la anacronía de Genette (1972) y la estructura entera del cuento, contado del final hacia el principio.',guia:'Se espera que el lector explique que Gérard Genette, en «Figures III» (1972), separa el tiempo de la historia (los hechos en su orden real, del nacimiento a la muerte de Práxedes) del tiempo del relato (el orden en que se cuentan, aquí invertido por completo), y llama anacronía a cualquier salto entre los dos. El cuento entero es una analepsis continua y extrema: cada hoja retrocede un paso más en la vida del personaje, y esa estructura no es un adorno, es la que produce el efecto central de la historia, la curiosidad de entender la causa de un final que ya se conocía desde el principio.',t:'Borges'},
{q:'Explica el paralelismo que el narrador establece entre la técnica de Hermenegildo Sarabia y el corte del combate en el «Quijote» de 1605, y qué logra ese paralelismo dentro del capítulo.',guia:'Se espera que el lector explique que el narrador compara, de forma explícita, el corte que Sarabia hace cada noche (dejar el cuchillo en el aire, justo antes del momento culminante) con el corte real que hace Miguel de Cervantes Saavedra en la primera parte del «Quijote» (1605), donde deja a don Quijote y a un vizcaíno con las espadas en alto, alegando que ahí se le acababa el manuscrito. El paralelismo logra dos cosas: legitima la técnica del cuentista de posada, mostrando que el corte de suspense no es un truco moderno sino un recurso con siglos de historia comprobable, y a la vez le da al lector del capítulo un dato real y fechado en medio de una historia inventada, cumpliendo la regla de la casa de no citar nunca una fecha o una obra que no sea comprobable.',t:'Cervantes'},
{q:'Explica qué quiere decir el mozo Prudencio Nabor cuando afirma que Sarabia «nunca mintió sobre lo que hacía, ni escondió el cuchillo que dejaba en el aire».',guia:'Se espera que el lector explique que Prudencio Nabor distingue entre ocultar información al público (lo que produciría una sorpresa final, sin aviso) y declarar, a la vista de todos, que falta lo más importante de la historia (lo que produce suspense, según la distinción de Alfred Hitchcock, vía François Truffaut, 1966): Sarabia no engañaba a los oyentes sobre el hecho de que la historia quedaba incompleta cada noche, y esa honestidad sobre el corte, no el corte en sí mismo, es lo que mantenía despierta a la posada entera, noche tras noche, dispuesta a pagar con tal de saber cómo seguía.',t:'Cervantes'},
{q:'Explica el experimento de Loftus y Palmer (1974) y qué demuestra sobre la relación entre el lenguaje y el recuerdo.',guia:'Se espera que el lector explique que Elizabeth Loftus y John Palmer, en 1974, mostraron el mismo video de un choque de autos a distintos grupos de personas, y cambiaron una sola palabra en la pregunta posterior (si los autos se habían «estrellado» o solo «chocado»), lo que bastó para que las estimaciones de velocidad cambiaran, y para que días después algunas personas juraran haber visto vidrios rotos que el video nunca mostró. El experimento demuestra que la memoria no es una grabación fija que se consulta después, sino que se reconstruye cada vez que se recuerda, y que información recibida después del hecho puede alterar el recuerdo del hecho mismo.',t:'Harari'},
{q:'Explica la relación que el ensayo establece entre los recuerdos de flash (Brown y Kulik, 1977) y el estudio del Challenger (Neisser y Harsch, 1992), y por qué ambos se enseñan siempre juntos.',guia:'Se espera que el lector explique que Roger Brown y James Kulik, en 1977, nombraron los recuerdos de flash: la sensación de que un momento de gran impacto quedó grabado con nitidez fotográfica en la memoria. Ulric Neisser y Nicole Harsch, en 1992, pusieron a prueba esa sensación con el caso real de la explosión del transbordador Challenger, comparando lo que los estudiantes recordaban al día siguiente con lo que recordaban dos años y medio después, y encontraron que casi la mitad se equivocaba en detalles importantes, mientras seguían sintiéndose completamente seguros. Los dos hallazgos se enseñan juntos porque, por separado, cada uno cuenta solo la mitad de la historia: uno describe la sensación de nitidez, y el otro demuestra que esa sensación no garantiza exactitud.',t:'Harari'},
{q:'Explica, con el ejemplo de la bomba bajo la mesa, la diferencia que Hitchcock establece entre el suspense y la sorpresa.',guia:'Se espera que el lector explique que, según Hitchcock, en la entrevista con Truffaut publicada en 1966, la sorpresa ocurre cuando algo inesperado pasa sin ningún aviso previo al público, como una bomba que estalla de pronto bajo una mesa, y produce apenas unos segundos de susto. El suspense, en cambio, ocurre cuando el público sabe, desde antes, que hay una bomba bajo la mesa y cuánto tiempo falta para que estalle, mientras los personajes siguen conversando de algo sin importancia, sin saberlo: la misma escena, con la sola diferencia de qué sabe el público y cuándo lo sabe, pasa de un susto breve a una tensión sostenida durante toda la conversación.',t:'Entrevista'},
{q:'Explica cómo Hitchcock concede, en la entrevista, el límite de su propia regla sobre el suspense, usando el ejemplo de «Psicosis» (1960).',guia:'Se espera que el lector explique que Hitchcock, después de defender el suspense como su herramienta preferida, admite que él mismo usó la sorpresa a propósito en la escena de la ducha de «Psicosis» (1960), matando a la protagonista principal a mitad de la película sin ningún aviso previo al público, porque en ese momento no quería que el espectador sufriera junto con el personaje esperando el golpe, sino que nadie, en ningún cine del mundo, lo viera venir. Esta concesión muestra que la propia regla de la bomba bajo la mesa no es una ley que Hitchcock obedezca siempre, sino una herramienta entre otras, que se elige según lo que la escena necesite.',t:'Entrevista'},
{q:'Explica por qué Rulfo dice que no quería que el lector supiera «de entrada quién estaba vivo y quién muerto» en «Pedro Páramo» (1955).',guia:'Se espera que el lector explique que Rulfo construye la novela con voces que se cruzan sin avisar si pertenecen a personajes vivos o a muertos que siguen hablando en Comala, y que esa falta de aviso es una decisión deliberada: quería que el lector fuera entendiendo la situación despacio, del mismo modo en que alguien que llega de fuera a un pueblo desconocido entiende sus historias por pedazos que al principio no calzan, en vez de recibir de entrada una explicación ordenada de quién es quién. La técnica reproduce, dentro de la lectura, la misma sensación de desorientación que vive el propio personaje de Juan Preciado al llegar a Comala.',t:'Quintero y Rulfo'},
{q:'Explica de dónde dice Rulfo que copió el desorden temporal de su narrativa, y qué relación establece esa respuesta entre la memoria y la estructura del relato.',guia:'Se espera que el lector explique que Rulfo afirma no haber inventado el desorden temporal de sus historias, sino haberlo copiado de cómo la gente de verdad recuerda su tierra cuando ya no vive en ella: saltando del entierro de ayer a la boda de hace treinta años sin ninguna transición ordenada. Con esa respuesta, Rulfo conecta la estructura fuera de orden de su narrativa con el funcionamiento real de la memoria humana, la misma idea que el ensayo de esta etapa desarrolla con los hallazgos de Loftus y Palmer (1974) y de Neisser y Harsch (1992): reordenar el tiempo de un relato no traiciona la memoria, la imita.',t:'Quintero y Rulfo'},
{q:'Explica la disputa central del careo entre la defensa y la objeción sobre contar en desorden, y qué es lo que las dos partes aceptan sin discutir.',guia:'Se espera que el lector explique que la defensa sostiene que el reorden temporal, apoyado en la elipsis de Iser (1976) y en el precepto in medias res de Horacio (hacia el 18 a.C.), crea significado y compromete más al lector que el orden llano, mientras que la objeción sostiene que el desorden es, con frecuencia, una muletilla de moda que disfraza una historia floja, y que la claridad cronológica respeta más al lector. El terreno común que las dos partes aceptan, sin embargo, es más grande de lo esperado: ambas rechazan el flashback que solo explica sin revelar nada nuevo, ambas condenan confundir el suspense con la sorpresa (Hitchcock, vía Truffaut, 1966), y ambas coinciden en que el orden de un relato es una decisión que debe declararse, no un accidente ni una moda copiada sin preguntarse por qué.',t:'Debate'},
{q:'¿Qué dato concreto propone el careo para acercar la disputa, y por qué ese dato resolvería mejor la cuestión que una opinión de crítico?',guia:'Se espera que el lector identifique que el careo propone estudios con lectores reales que comparen la comprensión y el interés del mismo relato contado una vez en orden lineal y otra vez reordenado, y que explique por qué ese dato, y no la opinión de un crítico o una preferencia de época, resolvería mejor la disputa: porque mediría el efecto real sobre quien recibe el texto, que es justamente lo que las dos posturas dicen defender (la defensa, que el reorden compromete más; la objeción, que confunde), en vez de quedarse en el terreno de la estética personal o de lo que está de moda en un momento dado.',t:'Debate'}
];

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue buscando el orden, la duración y lo que sabe el lector!','¡Muy buen trabajo!','¡Ya distingues la fábula de la trama!','¡Ya sabes cuándo un salto se gana su lugar!','¡Ningún suspense se te confunde con una sorpresa!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='⏳ ¡'+name+' completó la Etapa 7 de la Ruta del Hilo que Tira (El tiempo del relato)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

